# The micro:bit reads a sensor, decides, then acts.
# There is no board here, so random readings stand in for the sensor.
import random

for _ in range(5):
    temp = random.randint(14, 30)
    if temp > 25:
        print(f"{temp}C  fan ON")
    else:
        print(f"{temp}C  fan OFF")

// Binary and hexadecimal, computed in the browser.
// Try 42, 255 or 2026.
const values = [42, 255, 2026];

for (const n of values) {
  console.log(
    n,
    "->",
    "0b" + n.toString(2),
    "|",
    "0x" + n.toString(16).toUpperCase()
  );
}

// Two's complement for an 8-bit negative number.
const x = -42;
console.log("-42 in 8-bit two's complement:", (x & 0xff).toString(2).padStart(8, "0"));

# Recursion, lists and dictionaries.
def factorial(n):
    if n <= 1:                     # base case
        return 1
    return n * factorial(n - 1)    # recursive case

print("5! =", factorial(5))

results = {"Ada": 88, "Grace": 91, "Alan": 74}
for name, mark in sorted(results.items(), key=lambda kv: -kv[1]):
    print(f"{name:<6} {mark}  {'H1' if mark >= 90 else 'H2'}")

// Arrays, objects and a loop — same logic as Python, different syntax.
const results = [
  { name: "Ada", mark: 88 },
  { name: "Grace", mark: 91 },
  { name: "Alan", mark: 74 }
];

const average =
  results.reduce((sum, r) => sum + r.mark, 0) / results.length;
console.log("average:", average.toFixed(1));

for (const r of results) {
  console.log(`${r.name}: ${r.mark}`);
}
